//! Loads and runs every model in the repository.
//!
//! The repository is generated by `scripts/synthetic_models.py`, which builds
//! its graphs with `onnx.helper` and checks them with ONNX's own checker. A
//! checked graph is not a servable one: the checker says the protobuf is
//! well formed, not that ONNX Runtime can build a session for it, that its
//! operators are implemented on this platform, or that its first dimension is
//! really free. This runs each of them, which is the only way to know.
//!
//! It also fixes the batch claim. Every model here declares a dynamic first
//! dimension so that the server may merge independent requests into one call;
//! a model whose shapes quietly pinned it to one row would be served one
//! request at a time with nothing to say so.

use galemind_core::{
    Backend, BackendFactory, DataType, InferRequest, ModelArtifact, ModelConfig, ModelKey,
    ModelRef, Parameters, Tensor, TensorData, PLATFORM_ONNX,
};
use galemind_onnx::{OnnxBackendFactory, OnnxRuntimeConfig};
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn repository() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../models")
}

/// Every `<model>/<version>/model.onnx` in the repository.
fn model_files() -> Vec<(String, String, PathBuf)> {
    let root = repository();
    let mut found = Vec::new();

    let models = std::fs::read_dir(&root)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", root.display()))
        .filter_map(Result::ok);
    for model in models {
        if !model.path().is_dir() {
            continue;
        }
        let name = model.file_name().to_string_lossy().to_string();
        let versions = std::fs::read_dir(model.path())
            .expect("a readable model directory")
            .filter_map(Result::ok);
        for version in versions {
            let file = version.path().join("model.onnx");
            if file.is_file() {
                found.push((
                    name.clone(),
                    version.file_name().to_string_lossy().to_string(),
                    file,
                ));
            }
        }
    }
    found.sort();
    found
}

/// Loads a model file with the settings a server would use: one operator
/// thread, and the arena off.
fn load(name: &str, version: &str, path: &Path) -> Arc<dyn Backend> {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("cannot read {path:?}: {e}"));
    let artifact = ModelArtifact {
        key: ModelKey::new(name, version),
        platform: PLATFORM_ONNX.to_string(),
        digest: "test".to_string(),
        config: ModelConfig {
            platform: None,
            max_batch_size: Some(8),
            intra_op_threads: Some(1),
        },
        bytes,
    };

    OnnxBackendFactory::with_config(OnnxRuntimeConfig::default())
        .load(&artifact)
        .unwrap_or_else(|e| panic!("{name}/{version} cannot be loaded: {e}"))
}

/// Fills every declared input with `rows` rows of ones.
///
/// The values do not matter -- the weights are synthetic, so the outputs mean
/// nothing either -- but the shapes do, and they come from the model.
fn request(backend: &dyn Backend, rows: usize) -> InferRequest {
    let metadata = backend.metadata();
    let inputs = metadata
        .inputs
        .iter()
        .map(|input| {
            let width: i64 = input.shape.iter().skip(1).product();
            let count = rows * width as usize;
            let data = match input.datatype {
                DataType::Fp32 => TensorData::Fp32(vec![1.0; count]),
                DataType::Fp64 => TensorData::Fp64(vec![1.0; count]),
                DataType::Int64 => TensorData::Int64(vec![1; count]),
                other => panic!("no filler for a {other} input"),
            };
            let mut shape = vec![rows as i64];
            shape.extend(input.shape.iter().skip(1).copied());
            Tensor::new(&input.name, shape, data)
        })
        .collect();

    InferRequest {
        model: ModelRef::latest(&metadata.name),
        id: Some("zoo".to_string()),
        parameters: Parameters::new(),
        inputs,
        requested_outputs: Vec::new(),
    }
}

#[test]
fn the_repository_holds_the_whole_zoo() {
    let files = model_files();
    let names: Vec<&str> = files.iter().map(|(name, _, _)| name.as_str()).collect();

    for expected in [
        "building_energy",
        "building_energy_class",
        "energy_autoencoder",
        "feature_scaler",
        "load_forecast_tcn",
        "meter_digit_cnn",
        "occupancy_mlp",
        "stackgan_stage1",
        "stackgan_stage2",
        "thermal_cnn",
    ] {
        assert!(
            names.contains(&expected),
            "{expected} is missing; run `make models`. Found: {names:?}"
        );
    }
}

#[test]
fn every_model_in_the_repository_loads_and_answers() {
    for (name, version, path) in model_files() {
        let backend = load(&name, &version, &path);
        let metadata = backend.metadata();

        assert!(
            !metadata.inputs.is_empty(),
            "{name}/{version} declares no inputs"
        );
        assert!(
            !metadata.outputs.is_empty(),
            "{name}/{version} declares no outputs"
        );

        let response = backend
            .infer(&request(backend.as_ref(), 1))
            .unwrap_or_else(|e| panic!("{name}/{version} cannot answer a single row: {e}"));

        assert_eq!(
            response.outputs.len(),
            metadata.outputs.len(),
            "{name}/{version} returned a different number of outputs than it declares"
        );
        for output in &response.outputs {
            assert_eq!(
                output.rows().unwrap_or(0),
                1,
                "{name}/{version} output '{}' is not one row per input row",
                output.name
            );
            assert!(
                !output.data.is_empty(),
                "{name}/{version} output '{}' is empty",
                output.name
            );
        }
    }
}

/// The server merges independent requests into one call, so a model that
/// cannot take a batch cannot be served the way the rest are.
#[test]
fn every_model_takes_a_batch_of_rows() {
    for (name, version, path) in model_files() {
        let backend = load(&name, &version, &path);
        assert!(
            backend.metadata().is_batchable(),
            "{name}/{version} does not declare a dynamic batch dimension"
        );

        let rows = 3;
        let response = backend
            .infer(&request(backend.as_ref(), rows))
            .unwrap_or_else(|e| panic!("{name}/{version} cannot answer {rows} rows: {e}"));

        for output in &response.outputs {
            assert_eq!(
                output.rows().unwrap_or(0),
                rows,
                "{name}/{version} output '{}' did not return a row per input row",
                output.name
            );
        }
    }
}

/// A batch must be the same arithmetic as the rows run separately, or the
/// server's batching would change answers.
#[test]
fn a_batch_gives_each_row_the_answer_it_would_get_alone() {
    for (name, version, path) in model_files() {
        let backend = load(&name, &version, &path);

        let alone = backend.infer(&request(backend.as_ref(), 1)).unwrap();
        let batched = backend.infer(&request(backend.as_ref(), 4)).unwrap();

        for (single, batch) in alone.outputs.iter().zip(&batched.outputs) {
            let name = &single.name;
            // Every row of the batch is filled identically, so the batch's
            // first row must hold what the lone row held.
            match (&single.data, &batch.data) {
                (TensorData::Fp32(alone), TensorData::Fp32(batched)) => {
                    for (index, value) in alone.iter().enumerate() {
                        let in_batch = batched[index];
                        assert!(
                            (value - in_batch).abs() <= 1e-5 * value.abs().max(1.0),
                            "{name}/{version} output '{name}' element {index} differs \
                             between a lone row and a batch: {value} vs {in_batch}"
                        );
                    }
                }
                (TensorData::Int64(alone), TensorData::Int64(batched)) => {
                    assert_eq!(
                        alone[..],
                        batched[..alone.len()],
                        "{name}/{version} output '{name}' gave a different label in a batch"
                    );
                }
                // Nothing else appears in this repository; a new datatype
                // here would simply not be compared, so the zoo test above
                // is what keeps it honest.
                _ => {}
            }
        }
    }
}
